'use client';

import { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';

interface UserSettings {
  notificationsEnabled: boolean;
}

// Mock database - in a real app this would be your database
let userSettings: UserSettings = {
  notificationsEnabled: false
};

// Server Action to toggle notifications
export async function toggleNotifications() {
  'use server';

  // Toggle the notification preference
  userSettings.notificationsEnabled = !userSettings.notificationsEnabled;

  // Return the updated state
  return userSettings.notificationsEnabled;
}

export default function Home() {
  const [isPending, startTransition] = useTransition();
  const router = useRouter();
  const [notificationsEnabled, setNotificationsEnabled] = useState(userSettings.notificationsEnabled);

  const handleToggle = async () => {
    // Call the Server Action
    const newPreference = await toggleNotifications();

    // Update local state
    setNotificationsEnabled(newPreference);

    // Refresh the current page without redirecting
    startTransition(() => {
      router.refresh();
    });
  };

  return (
    <main className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6">Settings</h1>

      <div className="bg-white rounded-lg shadow-md p-6">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-medium text-gray-900">Notifications</h2>
            <p className="text-sm text-gray-500 mt-1">
              Enable or disable email notifications for updates and alerts
            </p>
          </div>

          <div className="flex items-center space-x-4">
            <span className={`text-sm font-medium ${
              notificationsEnabled ? 'text-green-600' : 'text-gray-500'
            }`}>
              {notificationsEnabled ? 'Enabled' : 'Disabled'}
            </span>

            <button
              onClick={handleToggle}
              disabled={isPending}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                notificationsEnabled ? 'bg-blue-600' : 'bg-gray-200'
              } ${isPending ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
            >
              <span 
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  notificationsEnabled ? 'translate-x-6' : 'translate-x-1'
                }`}
              />
            </button>
          </div>
        </div>

        {isPending && (
          <div className="mt-4 text-sm text-gray-500">
            Updating preferences...
          </div>
        )}
      </div>

      <div className="mt-6 text-sm text-gray-600">
        Current preference: <strong>{notificationsEnabled ? 'ON' : 'OFF'}</strong>
      </div>
    </main>
  );
}

